<script setup lang="ts">
import { computed, ref, watch } from "vue";
import { type PaymentIdentifierPolicy, type PaymentIdentifierCapabilities } from "@papilio/api";
import NumField from "@papilio/ui/NumField.vue";
const props=defineProps<{modelValue:PaymentIdentifierPolicy|null;capabilities:PaymentIdentifierCapabilities}>();
const emit=defineEmits<{"update:modelValue":[value:PaymentIdentifierPolicy|null];valid:[value:boolean]}>();
const enabled=ref(false),mode=ref<PaymentIdentifierPolicy["mode"]>("exact_requested"),adjustment=ref(""),step=ref("");
const labels={exact_requested:"Exact requested amount",rial_suffix4:"Four-digit identifier in the RIAL amount"};
watch(()=>props.modelValue,value=>{enabled.value=value!==null;mode.value=value?.mode??"exact_requested";adjustment.value=value?String(value.max_adjustment_rial):"";step.value=value?String(value.amount_step_rial):"";},{immediate:true});
const valid=computed(()=>!enabled.value||Boolean(adjustment.value&&step.value&&Number.isSafeInteger(Number(adjustment.value))&&Number(adjustment.value)>=0&&Number.isSafeInteger(Number(step.value))&&Number(step.value)>0&&props.capabilities.suffix_modulus%Number(step.value)===0&&props.capabilities.supported_modes.includes(mode.value)&&(mode.value!=="rial_suffix4"||props.capabilities.capacity&&Number(adjustment.value)<=props.capabilities.capacity.max_adjustment_rial&&Math.floor(Number(adjustment.value)/Number(step.value))+1<=props.capabilities.capacity.max_candidate_amounts)));
watch(valid,value=>emit("valid",value),{immediate:true});
function apply():void{if(!enabled.value){emit("update:modelValue",null);return;}if(!valid.value)return;emit("update:modelValue",{mode:mode.value,max_adjustment_rial:Number(adjustment.value),amount_step_rial:Number(step.value)});}
</script>
<template><section class="form-grid" aria-label="Payment identifier policy"><h4>Payment amount identifiers</h4><p>Without an explicit policy, new requests use their exact requested amount. Existing requests keep their saved payable amount and code.</p><p v-if="capabilities.capacity===null" class="hint-box" role="status">Identifier allocation is unavailable in this runtime. Historical codes remain readable; new four-digit allocations cannot be enabled.</p><dl v-else><dt>Runtime maximum adjustment</dt><dd>{{capabilities.capacity.max_adjustment_rial}} RIAL</dd><dt>Candidate amounts per allocation</dt><dd>{{capabilities.capacity.max_candidate_amounts}}</dd><dt>Active codes per receiving account</dt><dd>{{capabilities.capacity.max_active_codes}}</dd></dl><label class="check-row"><input v-model="enabled" type="checkbox" @change="apply"/>Set an explicit payment identifier policy</label><template v-if="enabled"><label class="field"><span>Payment identifier mode</span><select v-model="mode" @change="apply"><option v-for="value in capabilities.supported_modes" :key="value" :value="value" :disabled="value==='rial_suffix4'&&capabilities.capacity===null">{{labels[value]}}</option></select></label><NumField v-model="adjustment" label="Maximum identifier adjustment (RIAL)" @update:model-value="apply"/><NumField v-model="step" label="Payable amount step (RIAL)" @update:model-value="apply"/><p>The step must divide {{capabilities.suffix_modulus}}. The complete payable amount, including all {{capabilities.suffix_digits}} identifier digits, is credited after approval.</p><p v-if="!valid" class="message error" role="alert">Enter a nonnegative adjustment and a positive valid step within the displayed runtime capacity.</p></template></section></template>
